import pandas as pd

def laporan_aturan(df):
    pola = r'^[^@\s]+@[^@\s]+\.[^@\s]+$'
    aturan = {
        'umur_valid': df['umur'].between(0, 120),
        'email_valid': df['email'].str.match(pola, na=False),
        'id_unik': ~df.duplicated('id', keep=False),
    }
    return {k: int((~v).sum()) for k, v in aturan.items()}

